"""Calculer la moyenne d'une liste de nombres."""


def moyenne(valeurs):
    """Renvoie la moyenne de `valeurs`, ou 0 si la liste est vide."""
    if not valeurs:
        return 0
    total = 0
    for valeur in valeurs:
        total += valeur
    return total / len(valeurs)


if __name__ == "__main__":
    print(moyenne([1, 2, 3, 4]))

